const tableOrder = ["users", "territories", "clients", "orders", "order_items", "files"];

function authorized(request: Request) {
  return request.headers.get("x-db-refresh-key") === refreshKey;
}

function identifier(value: string) {
  return `"${value.replaceAll('"', '""')}"`;
}

function literal(value: unknown) {
  if (value === null || value === undefined) return "NULL";
  if (typeof value === "number") return Number.isFinite(value) ? String(value) : "NULL";
  if (typeof value === "boolean") return value ? "1" : "0";
  return `'${String(value).replaceAll("'", "''")}'`;
}

async function status(database: ReturnType<typeof db>) {
  const counts: Record<string, number> = {};
  for (const table of tableOrder) {
    const row = await database.prepare(`SELECT count(*) AS n FROM ${identifier(table)}`).first<{ n: number }>();
    counts[table] = Number(row?.n ?? 0);
  }
  let integrityCheck = "unavailable";
  let integrityError: string | undefined;
  try {
    const integrity = await database.prepare("PRAGMA integrity_check").all<Record<string, string>>();
    integrityCheck = String(Object.values(integrity.results?.[0] ?? {})[0] ?? "unknown");
  } catch (error) {
    integrityError = error instanceof Error ? error.message : String(error);
  }
  let foreignKeyErrors = -1;
  let foreignKeyError: string | undefined;
  try {
    const foreignKeys = await database.prepare("PRAGMA foreign_key_check").all();
    foreignKeyErrors = (foreignKeys.results ?? []).length;
  } catch (error) {
    foreignKeyError = error instanceof Error ? error.message : String(error);
  }
  return {
    counts,
    integrity_check: integrityCheck,
    foreign_key_errors: foreignKeyErrors,
    ...(integrityError ? { integrity_error: integrityError } : {}),
    ...(foreignKeyError ? { foreign_key_error: foreignKeyError } : {}),
  };
}

async function exportSql(database: ReturnType<typeof db>) {
  const schemaRows = await database.prepare(
    "SELECT name,sql FROM sqlite_master WHERE type='table' AND name IN ('users','territories','clients','orders','order_items','files')"
  ).all<{ name: string; sql: string }>();
  const schemas = new Map((schemaRows.results ?? []).map((row) => [row.name, row.sql]));
  const lines = ["-- Backup ordini-db prima dell'import 2026-10-01", "PRAGMA defer_foreign_keys = true;"];
  for (const table of [...tableOrder].reverse()) lines.push(`DROP TABLE IF EXISTS ${identifier(table)};`);
  for (const table of tableOrder) {
    const schema = schemas.get(table);
    if (!schema) throw new Error(`Schema mancante per ${table}`);
    lines.push(`${schema};`);
    const rows = await database.prepare(`SELECT * FROM ${identifier(table)} ORDER BY id`).all<Record<string, unknown>>();
    for (const row of rows.results ?? []) {
      const columns = Object.keys(row);
      lines.push(`INSERT INTO ${identifier(table)} (${columns.map(identifier).join(",")}) VALUES (${columns.map((column) => literal(row[column])).join(",")});`);
    }
  }
  lines.push("PRAGMA foreign_keys = ON;");
  return lines.join("\n") + "\n";
}

export async function GET(request: Request) {
  if (!authorized(request)) return new Response("Not found", { status: 404 });
  const database = db();
  if (new URL(request.url).searchParams.get("action") === "backup") {
    return new Response(await exportSql(database), {
      headers: {
        "content-type": "application/sql; charset=utf-8",
        "content-disposition": 'attachment; filename="backup_ordini_db_pre_import_2026-10-01.sql"',
      },
    });
  }
  return Response.json(await status(database));
}

export async function POST(request: Request) {
  if (!authorized(request)) return new Response("Not found", { status: 404 });
  const database = db();
  const firstInsert = importStatements.findIndex((statement) => /^INSERT\s/i.test(statement));
  const setup = firstInsert < 0 ? importStatements : importStatements.slice(0, firstInsert);
  const inserts = firstInsert < 0 ? [] : importStatements.slice(firstInsert);
  await database.batch(setup.map((statement) => database.prepare(statement)));
  for (let index = 0; index < inserts.length; index += 50) {
    await database.batch(inserts.slice(index, index + 50).map((statement) => database.prepare(statement)));
  }
  return Response.json({ ok: true, ...(await status(database)) });
}
